using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using Microsoft.Win32;using System.IO.Compression;

sealed partial class Companion {

 internal readonly string[] Actions={"New note","Note view","Task view","New task list","Region capture","Capture window","Full screen","Repeat capture","Captures","Templates","Preview note","Attach file"};

 internal void DoAction(string a){switch(a){case "New note":NewNote("Quick note","");break;case "Note view":SetView("Notes");break;case "Checklist":case "Task view":SetView("Tasks");break;case "New task list":NewNote("Task list","");SetView("Tasks");break;case "Region capture":BeginCapture("region");break;case "Capture window":BeginCapture("window");break;case "Full screen":BeginCapture("screen");break;case "Repeat capture":BeginCapture("repeat");break;case "Captures":CaptureShelf();break;case "Templates":Templates();break;case "Preview note":Preview();break;case "Attach file":Attach();break;}}

 internal void BuildQuick(){quick.Items.Clear();foreach(string action in store.Pref.Quick??new string[0]){string chosen=action;if(Actions.Contains(chosen))Add(quick,chosen,()=>DoAction(chosen));}quick.LayoutStyle=ToolStripLayoutStyle.HorizontalStackWithOverflow;InstallFocusTabs();}

 internal void Settings(){using(var f=Dialog("Companion settings",650,780)){var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};var column=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,Padding=new Padding(0,0,15,20)};column.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));scroll.Controls.Add(column);Action<string> label=text=>column.Controls.Add(new Label{Text=text,AutoSize=true,MaximumSize=new Size(540,0),Margin=new Padding(0,10,0,8)});label("Files at a glance");var explorerPreview=new CheckBox{Text="Enable Explorer previews · select a file and press Space",AutoSize=true,Checked=store.Pref.FilePreviewEnabled};explorerPreview.CheckedChanged+=(s,e)=>{SetFilePreview(explorerPreview.Checked);if(explorerPreview.Checked!=store.Pref.FilePreviewEnabled)explorerPreview.Checked=store.Pref.FilePreviewEnabled;};column.Controls.Add(explorerPreview);label("Optional, off by default. Applies immediately. Works while Companion runs, including in the tray. Turn it off if you use QuickLook or Peek. Files > Preview file works without this switch. Images, GIFs, audio, video, PDFs, Markdown and text are supported. Document previews use WebView2 when available; other formats show file details and Open in default app.");label("Your notes, your way");label("Companion home · notes, captures, attachments and templates");var home=new TextBox{Text=store.Home,Width=540};column.Controls.Add(home);var browse=new Button{Text="Choose an existing or new home…",AutoSize=true};browse.Click+=(s,e)=>{string chosen=ModernFolder.Pick(f.Handle,"Choose your Companion home");if(chosen!=null)home.Text=chosen;};column.Controls.Add(browse);label("Changing the home connects another folder. Your current files stay where they are. Use Back up home before moving to another computer.");var theme=new ThemeComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=300};theme.Items.AddRange(new object[]{"Sketchbook","Charcoal","Paper","Plum","Candy","Forest","Blueprint"});theme.SelectedItem=store.Pref.Theme;theme.SelectedIndexChanged+=(s,e)=>ApplyTheme(theme.Text);label("Appearance · changes apply immediately");column.Controls.Add(theme);var minimal=new CheckBox{Text="Use the minimal memo view while floating",AutoSize=true,Checked=store.Pref.Memo};minimal.CheckedChanged+=(s,e)=>SetMemo(minimal.Checked);column.Controls.Add(minimal);var borderless=new CheckBox{Text="Use a borderless floating memo",AutoSize=true,Checked=store.Pref.Borderless};borderless.CheckedChanged+=(s,e)=>{store.Pref.Borderless=borderless.Checked;ApplyFloating();store.SavePrefs();};column.Controls.Add(borderless);label("Floating window opacity (%) · tabbed views stay opaque");var opacity=new ThemeNumber{Minimum=30,Maximum=100,Value=Math.Max(30,Math.Min(100,store.Pref.Opacity)),Width=120};opacity.ValueChanged+=(s,e)=>{store.Pref.Opacity=(int)opacity.Value;ApplyFloating();store.SavePrefs();};column.Controls.Add(opacity);var view=new ThemeComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=300};view.Items.AddRange(new object[]{"Last note","Tasks"});view.SelectedItem=store.Pref.StartupView;label("When opening Companion");column.Controls.Add(view);var startup=new CheckBox{Text="Open Companion when I sign in to Windows",AutoSize=true,Checked=StartupEnabled()};column.Controls.Add(startup);var quiet=new CheckBox{Text="Start quietly in the tray",AutoSize=true,Checked=StartupQuiet()};column.Controls.Add(quiet);var trayClose=new CheckBox{Text="Closing the window keeps shortcuts available in the tray",AutoSize=true,Checked=store.Pref.TrayClose};column.Controls.Add(trayClose);

 label("Global shortcuts · press your chosen combination in each box. Leave blank to disable.");TextBox note=HotkeyBox(store.Pref.NoteKey),region=HotkeyBox(store.Pref.RegionKey),window=HotkeyBox(store.Pref.WindowKey);foreach(var pair in new[]{Tuple.Create("Quick note",note),Tuple.Create("Capture region",region),Tuple.Create("Capture active window",window)}){label(pair.Item1);column.Controls.Add(pair.Item2);}label("Quick actions · choose which buttons appear below the top bar");var choices=new CheckedListBox{Height=150,Width=530,CheckOnClick=true};foreach(string a in Actions)choices.Items.Add(a,(store.Pref.Quick??new string[0]).Contains(a));column.Controls.Add(choices);label("Capture delay (seconds) · useful for menus and tooltips");var delay=new ThemeNumber{Minimum=0,Maximum=10,Value=store.Pref.Delay,Width=120};column.Controls.Add(delay);label("Save after a typing pause (seconds)");var pause=new ThemeNumber{Minimum=1,Maximum=30,DecimalPlaces=1,Increment=.5m,Value=Math.Max(1,Math.Min(30,store.Pref.SavePause/1000m)),Width=120};column.Controls.Add(pause);label("Capture folder");var destination=new TextBox{Text=CaptureRoot,Width=530};column.Controls.Add(destination);var chooseCaptures=new Button{Text="Choose capture folder…",AutoSize=true};chooseCaptures.Click+=(s,e)=>{var chosen=ModernFolder.Pick(f.Handle,"Where should captures be saved?");if(chosen!=null)destination.Text=chosen;};column.Controls.Add(chooseCaptures);label("Screenshot file format");var captureFormat=new ThemeComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};captureFormat.Items.AddRange(new object[]{"PNG","JPEG"});captureFormat.SelectedItem=store.Pref.CaptureFormat;captureFormat.SelectedIndexChanged+=(s,e)=>{store.Pref.CaptureFormat=captureFormat.Text;store.SavePrefs();};column.Controls.Add(captureFormat);label("After a capture");var after=new ThemeComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=300};after.Items.AddRange(new object[]{"Quick actions","Save and copy","Copy only","Preview and annotate","Show in folder","Open in Library"});after.SelectedItem=store.Pref.AfterCapture;column.Controls.Add(after);var notice=new CheckBox{Text="Show a small notification when a capture is copied",AutoSize=true,Checked=store.Pref.CaptureNotice};column.Controls.Add(notice);var captureButtonSetting=new CheckBox{Text="Show a floating one-click capture button",AutoSize=true,Checked=store.Pref.CaptureButton};column.Controls.Add(captureButtonSetting);var frame=new CheckBox{Text="Include the window frame in window captures",AutoSize=true,Checked=store.Pref.Frame};column.Controls.Add(frame);var backup=new Button{Text="Back up home as ZIP…",AutoSize=true};backup.Click+=(s,e)=>Backup();column.Controls.Add(backup);var folder=new Button{Text="Open Companion home",AutoSize=true};folder.Click+=(s,e)=>Open(store.Home);column.Controls.Add(folder);label("Link the Captures folder using Library’s Add folder. New saved captures will appear through Library’s folder refresh/watch workflow. Companion does not need Library running.");var copy=new Button{Text="Copy captures folder path",AutoSize=true};copy.Click+=(s,e)=>Clipboard.SetText(CaptureRoot);column.Controls.Add(copy);var library=new Button{Text="Open captures in Library",AutoSize=true};library.Click+=(s,e)=>OpenCapturesLibrary();column.Controls.Add(library);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="Save settings",AutoSize=true,Height=38};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};bottom.Controls.Add(save);bottom.Controls.Add(cancel);save.Click+=(s,e)=>{try{string[] keys={note.Text,region.Text,window.Text};if(keys.Where(k=>k.Length>0).Distinct().Count()!=keys.Count(k=>k.Length>0))throw new Exception("Choose different shortcuts for each action.");foreach(string k in keys)ParseShortcut(k);if(!SaveNow())return;if(!Path.GetFullPath(home.Text).Equals(store.Home,StringComparison.OrdinalIgnoreCase)){store.Connect(home.Text);current=null;RefreshNotes();if(store.Notes.Count==0)NewNote("Quick note","");else SelectNote(store.Notes[0]);}store.Pref.Memo=minimal.Checked;store.Pref.Borderless=borderless.Checked;store.Pref.Opacity=(int)opacity.Value;ApplyFloating();store.Pref.NoteKey=note.Text;store.Pref.RegionKey=region.Text;store.Pref.WindowKey=window.Text;store.Pref.TrayClose=trayClose.Checked;store.Pref.Frame=frame.Checked;store.Pref.AfterCapture=Convert.ToString(after.SelectedItem);store.Pref.CaptureNotice=notice.Checked;store.Pref.CaptureButton=captureButtonSetting.Checked;if(store.Pref.CaptureButton)ShowCaptureButton();else if(captureButton!=null)captureButton.Hide();Directory.CreateDirectory(destination.Text);store.Pref.CaptureFolder=Path.GetFullPath(destination.Text);Store.Atomic(Path.Combine(Shared,"capture-settings.json"),Store.Json.Serialize(new{path=store.Pref.CaptureFolder}));store.Pref.SavePause=(int)(pause.Value*1000);saveTimer.Interval=store.Pref.SavePause;store.Pref.Delay=(int)delay.Value;store.Pref.StartupView=Convert.ToString(view.SelectedItem);store.Pref.Quick=choices.CheckedItems.Cast<string>().ToArray();SetStartup(startup.Checked,quiet.Checked);ApplyTheme(Convert.ToString(theme.SelectedItem));BuildQuick();RegisterShortcuts();f.Close();}catch(Exception ex){MessageBox.Show(f,ex.Message,"Settings need a check");}};f.Controls.Add(scroll);f.Controls.Add(bottom);ThemeControls(f);f.ShowDialog(this);}}

 internal TextBox HotkeyBox(string value){var box=new TextBox{ReadOnly=true,Text=value,Width=330};box.KeyDown+=(s,e)=>{e.SuppressKeyPress=true;if(e.KeyCode==Keys.Back||e.KeyCode==Keys.Delete){box.Text="";return;}if(e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.Menu||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.LWin||e.KeyCode==Keys.RWin)return;box.Text=e.KeyData.ToString();};return box;}

 internal bool StartupEnabled(){if(Program.Test!=null)return false;try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))return k!=null&&k.GetValue("JagoCompanionPreview")!=null;}catch{return false;}}

 internal bool StartupQuiet(){if(Program.Test!=null)return false;try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))return k!=null&&Convert.ToString(k.GetValue("JagoCompanionPreview")).Contains("--tray");}catch{return false;}}

 internal void SetStartup(bool enabled,bool quiet){if(Program.Test!=null)return;using(var k=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(enabled)k.SetValue("JagoCompanionPreview","\""+Application.ExecutablePath+"\""+(quiet?" --tray":""));else k.DeleteValue("JagoCompanionPreview",false);}}

 internal void Backup(){if(!SaveNow())return;using(var pick=new System.Windows.Forms.SaveFileDialog{Filter="ZIP backup (*.zip)|*.zip",FileName="Jago-Companion-"+DateTime.Now.ToString("yyyy-MM-dd")+".zip"})if(pick.ShowDialog(this)==DialogResult.OK){string output=Path.GetFullPath(pick.FileName);if(output.StartsWith(store.Home.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)){Tell("Choose a backup destination outside the Companion home.");return;}if(File.Exists(output)){Tell("Choose a new backup filename.");return;}using(var archive=ZipFile.Open(output,ZipArchiveMode.Create)){foreach(string file in SafeFiles(store.Home,"*",0))archive.CreateEntryFromFile(file,store.Relative(file),CompressionLevel.Optimal);}Tell("Home backed up · settings remain separate on this computer");}}

 internal void Help(){using(var f=Dialog("Jago Companion · help & rights",660,650)){var text=new RichTextBox{Dock=DockStyle.Fill,ReadOnly=true,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",11),Text="Catch an idea. Keep it moving.\n\nNotes autosave as Markdown in your Companion home. Make notebooks with More > Move to notebook. Search includes note text; Favourites keeps starred notes close. Task view reads your - [ ] task lines. Switching Note view and Task view keeps the same page. New creates another page. Spelling is optional beside the font controls. Shift-click selects a range of pages, and Ctrl/Alt-click toggles individual pages. Delete selected moves them to Trash; Ctrl+Z there restores the last deletion.\n\nCtrl+N: quick note\nCtrl+S: save now\nCtrl+F: find in this note\nCtrl+Shift+F: search all notes\nCtrl+Shift+P: styled Markdown preview\nCtrl+Z / Ctrl+Y: normal text undo and redo\n\nCapture a region, choose an application window, or repeat your last capture. Captures save locally and open a preview by default. Click the saved-file line or Show in folder to locate the saved file. Choose PNG/JPEG in Settings. Save edited copy preserves the original; Float image reference keeps a copy above your work. Text annotations join the drawing tools. Capture centre explains the taskbar shortcut and lets you choose its one-click action. Normal Capture clicks start region capture; the chooser is optional. Annotate, crop or use solid redaction, then Copy or Save. Nothing uploads. Window capture brings a visible window forward; minimised and protected content are not supported in this preview.\n\nWindow > Compact gives you a small note surface. Always on top pins it above your other apps; Lock position prevents accidental moves/resizes. Both can be changed in Window. Each sticky has its own font, background opacity and appearance. Text stays opaque. Rounded corners and a coloured top strip are optional. Its controls reveal on hover; right-click its title to show them permanently.\n\nSettings lets you change global shortcuts, quick actions, startup and the home folder. Conflicting shortcuts are reported. Closing can keep the tray active; Quit from the tray exits fully.\n\nTemplates includes notes, project briefs, README starters and an email signature builder. HTML preview is sandboxed in your browser. Test signatures in your email app before using them.\n\nIn Workscape, Companion can be a tab or a narrow adjustable side panel. Floating capture previews remain available. Saved notes stay local even when the tab closes.\n\nOpen source. Free forever. Personal, professional and commercial use are welcome. Your files and imported assets retain their own licences.\n\nJago Companion 0.7.0 preview\nMade by Cameron Jago Lis Illustrates."};f.Controls.Add(text);ThemeControls(f);f.ShowDialog(this);}}

 internal void Templates(){using(var f=Dialog("Reusable templates",630,480)){var list=new ListBox{Dock=DockStyle.Fill};var templates=new Dictionary<string,string>{{"Blank note","# Untitled\n\n"},{"Project brief","# Project brief\n\n## Aim\n\n## Deliverables\n\n- [ ] First deliverable\n\n## References\n\n## Next steps\n"},{"Daily checklist","# "+DateTime.Now.ToString("dddd, d MMMM")+"\n\n- [ ] Priority\n- [ ] Next step\n\n## Notes\n"},{"README starter","# Project name\n\nA short explanation of what this project does.\n\n## Getting started\n\n## Usage\n\n## About & rights\n"}};foreach(string file in Directory.GetFiles(Path.Combine(store.Home,"Templates"),"*.md"))if(new FileInfo(file).Length<262144)templates[Path.GetFileNameWithoutExtension(file)]=File.ReadAllText(file);list.Items.AddRange(templates.Keys.Cast<object>().ToArray());var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48};var use=new Button{Text="Create note",AutoSize=true};use.Click+=(s,e)=>{if(list.SelectedItem==null)return;string name=Convert.ToString(list.SelectedItem);f.Close();NewNote(name,templates[name]);};bottom.Controls.Add(use);var sig=new Button{Text="Email signature / HTML…",AutoSize=true};sig.Click+=(s,e)=>{f.Close();SignatureBuilder();};bottom.Controls.Add(sig);f.Controls.Add(list);f.Controls.Add(bottom);ThemeControls(f);f.ShowDialog(this);}}

 internal void SignatureBuilder(){using(var f=new SignatureDesigner(this))f.ShowDialog(this);}

}
